CREATE TYPE public.app_role AS ENUM ('patient','doctor','admin');
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, display_name text NOT NULL CHECK (length(display_name) BETWEEN 2 AND 100), patient_code uuid NOT NULL UNIQUE DEFAULT gen_random_uuid(), consent_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles (user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL);
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_role ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
CREATE TABLE public.care_connections (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), patient_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, doctor_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected','revoked')), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(patient_id,doctor_id), CHECK(patient_id<>doctor_id));
GRANT SELECT ON public.care_connections TO authenticated; GRANT ALL ON public.care_connections TO service_role;
ALTER TABLE public.care_connections ENABLE ROW LEVEL SECURITY;
CREATE POLICY connection_participants ON public.care_connections FOR SELECT TO authenticated USING(auth.uid() IN (patient_id,doctor_id));
CREATE POLICY profile_participants ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid() OR EXISTS(SELECT 1 FROM public.care_connections c WHERE (c.patient_id=profiles.id AND c.doctor_id=auth.uid() AND c.status='approved') OR (c.doctor_id=profiles.id AND c.patient_id=auth.uid())));
CREATE TABLE public.admin_invitations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL CHECK(length(email)<=255), token_hash text NOT NULL UNIQUE, expires_at timestamptz NOT NULL DEFAULT now()+interval '7 days', used_at timestamptz, created_by uuid);
GRANT ALL ON public.admin_invitations TO service_role;
ALTER TABLE public.admin_invitations ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.create_admin_invitation(_email text) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE token text; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Acesso restrito'; END IF; IF length(_email)>255 OR _email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' THEN RAISE EXCEPTION 'Email inválido'; END IF; token:=gen_random_uuid()::text||gen_random_uuid()::text; INSERT INTO public.admin_invitations(email,token_hash,created_by) VALUES(lower(trim(_email)),md5(token),auth.uid()); RETURN token; END $$;
REVOKE ALL ON FUNCTION public.create_admin_invitation(text) FROM PUBLIC, anon; GRANT EXECUTE ON FUNCTION public.create_admin_invitation(text) TO authenticated;
CREATE FUNCTION public.on_account_created() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE selected_role public.app_role; invitation_id uuid; BEGIN IF coalesce(NEW.raw_user_meta_data->>'consent','false')<>'true' THEN RAISE EXCEPTION 'Consentimento obrigatório'; END IF; IF length(trim(coalesce(NEW.raw_user_meta_data->>'display_name','')))<2 OR length(trim(NEW.raw_user_meta_data->>'display_name'))>100 THEN RAISE EXCEPTION 'Nome inválido'; END IF; selected_role:=CASE NEW.raw_user_meta_data->>'account_role' WHEN 'doctor' THEN 'doctor'::public.app_role WHEN 'admin' THEN 'admin'::public.app_role ELSE 'patient'::public.app_role END; IF selected_role='admin' THEN SELECT id INTO invitation_id FROM public.admin_invitations WHERE email=lower(NEW.email) AND token_hash=md5(coalesce(NEW.raw_user_meta_data->>'invite','')) AND used_at IS NULL AND expires_at>now() FOR UPDATE; IF invitation_id IS NULL THEN RAISE EXCEPTION 'Convite inválido ou expirado'; END IF; UPDATE public.admin_invitations SET used_at=now() WHERE id=invitation_id; END IF; INSERT INTO public.profiles(id,display_name) VALUES(NEW.id,trim(NEW.raw_user_meta_data->>'display_name')); INSERT INTO public.user_roles(user_id,role) VALUES(NEW.id,selected_role); RETURN NEW; END $$;
CREATE TRIGGER create_account_profile AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.on_account_created();
CREATE FUNCTION public.request_connection(_code uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE patient uuid; BEGIN IF NOT public.has_role(auth.uid(),'doctor') THEN RAISE EXCEPTION 'Apenas médicos podem solicitar conexão'; END IF; SELECT p.id INTO patient FROM public.profiles p JOIN public.user_roles r ON r.user_id=p.id WHERE p.patient_code=_code AND r.role='patient'; IF patient IS NULL THEN RAISE EXCEPTION 'ID não disponível'; END IF; INSERT INTO public.care_connections(patient_id,doctor_id) VALUES(patient,auth.uid()) ON CONFLICT(patient_id,doctor_id) DO UPDATE SET status='pending' WHERE care_connections.status IN ('rejected','revoked'); END $$;
REVOKE ALL ON FUNCTION public.request_connection(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.request_connection(uuid) TO authenticated;
CREATE FUNCTION public.respond_connection(_id uuid,_status text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF _status NOT IN ('approved','rejected','revoked') THEN RAISE EXCEPTION 'Resposta inválida'; END IF; UPDATE public.care_connections SET status=_status WHERE id=_id AND patient_id=auth.uid() AND ((status='pending' AND _status IN ('approved','rejected')) OR (status='approved' AND _status='revoked')); IF NOT FOUND THEN RAISE EXCEPTION 'Solicitação não disponível'; END IF; END $$;
REVOKE ALL ON FUNCTION public.respond_connection(uuid,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.respond_connection(uuid,text) TO authenticated;
REVOKE ALL ON FUNCTION public.on_account_created() FROM PUBLIC,anon,authenticated;